// Render without our server: the page talks the Comfy API v2 (what the official comfy-sdk speaks) with
// the visitor's own Comfy API key, kept in this browser's localStorage. Comfy Cloud doesn't answer
// browser (CORS) calls as far as we can tell, so the page usually goes through worker/ (a pass-through
// Cloudflare Worker the visitor deploys); a self-hosted comfy-api-proxy started with
// --enable-cors-header <page origin> works directly. See docs/LIVE_RENDER.md.
//
// The graphs are the committed workflows/*.json (generated by server/workflow.py, checked in CI) with
// the same inputs set by node id as server/render.py sets them, so both paths run the same workflows.

import stage1Graph from '../../workflows/stage1_layout_api.json' with { type: 'json' };
import lookGraph from '../../workflows/look_still_depth_api.json' with { type: 'json' };

export const COMFY_CLOUD = 'https://cloud.comfy.org';

// Node ids, as in server/workflow.py (NODES, LOOK_NODES)
export const NODES = { layout: '10', look: '12', prompt: '20', latent: '30', audio: '31', seed: '40', output: '60' };
export const LOOK_NODES = { depth: '10', prompt: '20', latent: '30', sampler: '40', output: '60' };

const LOOK_PIXELS = 1024 * 1024;

/** Python's round() (halves to even), so the sizes below match server/workflow.py exactly. */
function pyRound(x) {
  const r = Math.round(x);
  return Math.abs(x % 1) === 0.5 && r % 2 ? r - 1 : r;
}

/** The Layout-to-Render recipe for layout clips: dims divisible by 64, 8k+1 frames. */
export function checkDims(width, height, frames, multiple = 64) {
  if (width % multiple || height % multiple) throw new Error(`width and height must be divisible by ${multiple}, got ${width}x${height}`);
  if (frames < 9 || (frames - 1) % 8) throw new Error(`frames must be 8k+1 (65, 97, 121...), got ${frames}`);
}

/** Stage 1 runs at the clip size up to 960 wide; bigger layouts run at half size (1920x1088 -> 960x544). */
export function stage1Size(width, height) {
  while (width > 960) [width, height] = [Math.floor(width / 2), Math.floor(height / 2)];
  return [width - (width % 32), height - (height % 32)];
}

/** Generation size for a look still: about 1 MP, same aspect, divisible by 16. */
export function lookSize(width, height) {
  if (width % 64 || height % 64) throw new Error(`width and height must be divisible by 64, got ${width}x${height}`);
  const scale = (LOOK_PIXELS / (width * height)) ** 0.5;
  const gw = Math.max(16, pyRound((width * scale) / 16) * 16);
  const gh = Math.max(16, pyRound((gw * height) / width / 16) * 16);
  return [gw, gh];
}

/** The `core/ASSET` reference the SDK substitutes for an uploaded file. */
export function assetRef(asset) {
  const info = { id: asset.id };
  if (asset.hash) info.hash = asset.hash;
  if (asset.file_path) info.file_path = asset.file_path;
  return { __type: 'core/ASSET', info };
}

const clone = (g) => JSON.parse(JSON.stringify(g));

/** Stage-1 graph as server/render.py submits it. `layout`/`look` are uploaded assets ({id, ...}). */
export function buildStage1({ layout, look, prompt, width, height, frames, seed = 42 }) {
  checkDims(width, height, frames);
  if (!prompt.trim()) throw new Error('prompt is empty');
  const [w, h] = stage1Size(width, height);
  checkDims(w, h, frames, 32);
  const g = clone(stage1Graph);
  g[NODES.layout].inputs.file = assetRef(layout);
  g[NODES.look].inputs.image = assetRef(look);
  g[NODES.prompt].inputs.text = prompt;
  Object.assign(g[NODES.latent].inputs, { width: w, height: h, length: frames });
  g[NODES.audio].inputs.frames_number = frames;
  g[NODES.seed].inputs.noise_seed = seed;
  return g;
}

/** Look-still graph (depth map of frame 0 + prompt -> still at width x height), as server/render.py submits it. */
export function buildLookStill({ depth, prompt, width, height, seed = 42, strength = 1.0 }) {
  if (!prompt.trim()) throw new Error('prompt is empty');
  const [gw, gh] = lookSize(width, height);
  const g = clone(lookGraph);
  g[LOOK_NODES.depth].inputs.image = assetRef(depth);
  Object.assign(g['11'].inputs, { width: gw, height: gh });
  g['5'].inputs.strength = strength;
  g[LOOK_NODES.prompt].inputs.text = prompt;
  Object.assign(g[LOOK_NODES.latent].inputs, { width: gw, height: gh });
  g[LOOK_NODES.sampler].inputs.seed = seed;
  Object.assign(g['51'].inputs, { width, height });
  return g;
}

// ---------- settings (this browser only) ----------

const KEY_KEY = 'ocs.comfyKey';
const BASE_KEY = 'ocs.comfyBase';
const LOCAL = new Set(['localhost', '127.0.0.1', '[::1]']);

/** Clean up a typed Comfy API URL ('' = Comfy Cloud). The key goes there, so only https (or http on this machine). */
export function normalizeBase(input) {
  let s = (input || '').trim();
  if (!s) return COMFY_CLOUD;
  if (!/^[a-z][a-z0-9+.-]*:\/\//i.test(s)) s = `https://${s}`;
  const u = new URL(s);
  if (u.protocol !== 'https:' && !(u.protocol === 'http:' && LOCAL.has(u.hostname))) {
    throw new Error('Use an https:// URL (http only for localhost): your key is sent there.');
  }
  // A dotless name is almost always the key pasted into the wrong field: refuse it before the key
  // goes out as a DNS lookup or ends up on screen (docs/SECURITY.md, finding 2).
  if (!LOCAL.has(u.hostname) && !u.hostname.includes('.')) {
    throw new Error('That isn’t a web address (did the key go in the “via” field?). Use the relay’s full URL, or leave it blank.');
  }
  if (u.search || u.hash || u.username || u.password) throw new Error('Leave out ?query, #fragment and user:password@');
  return `${u.origin}${u.pathname}`.replace(/\/+$/, '').replace(/\/api\/v2$/, '');
}

/** {key, base} saved in this browser; key '' when unset or storage is blocked. */
export function loadCloud(storage = globalThis.localStorage) {
  try {
    return { key: storage?.getItem(KEY_KEY) || '', base: normalizeBase(storage?.getItem(BASE_KEY) || '') };
  } catch {
    return { key: '', base: COMFY_CLOUD };
  }
}

export function saveCloud({ key, base }, storage = globalThis.localStorage) {
  try {
    if (key) storage.setItem(KEY_KEY, key);
    else storage.removeItem(KEY_KEY);
    if (base && base !== COMFY_CLOUD) storage.setItem(BASE_KEY, base);
    else storage.removeItem(BASE_KEY);
  } catch {
    // private mode / blocked storage: the key is only kept for this page view
  }
}

// ---------- Comfy API v2 client ----------

const HINTS = {
  401: 'the API key was refused: check it on platform.comfy.org',
  402: 'not enough Comfy credits on this account',
  403: 'this key may not use the API (Comfy Cloud API access needs a paid plan)',
};

const MAX_MESSAGE = 300;

/** An upstream or browser message made safe for the status line: the key cut out, one short line of text. */
export function redact(message, key) {
  let s = String(message ?? '');
  if (key) s = s.split(key).join('[your key]');
  s = s.replace(/[\u0000-\u001f\u007f]+/g, ' ').trim();
  return s.length > MAX_MESSAGE ? `${s.slice(0, MAX_MESSAGE - 1)}…` : s;
}

async function apiError(res, key) {
  const body = await res.json().catch(() => ({}));
  const e = body?.error;
  const raw = (e && typeof e === 'object' ? e.message : e) || HINTS[res.status] || `${res.status} ${res.statusText}`;
  const msg = redact(raw, key);
  const err = new Error(HINTS[res.status] && !msg.includes(HINTS[res.status]) ? `${msg} (${HINTS[res.status]})` : msg);
  err.status = res.status;
  err.code = e?.code;
  return err;
}

// Comfy keys are one token of printable ASCII; anything else can't go in a header anyway.
const KEY_SHAPE = /^[\x21-\x7e]{1,512}$/;

const newKey = () => globalThis.crypto?.randomUUID?.() ?? `ocs-${Date.now()}-${Math.random().toString(36).slice(2)}`;

/**
 * A small fetch client for the Comfy API v2 at `base` (Comfy Cloud, the worker/ relay, or a
 * comfy-api-proxy). The key goes in an Authorization header to `base` only.
 */
export function comfyClient({ base = COMFY_CLOUD, key, fetchFn = fetch }) {
  if (!key) throw new Error('Add your Comfy API key first.');
  // A pasted key with a stray space or newline makes fetch throw an error that quotes the whole header.
  if (!KEY_SHAPE.test(key)) throw new Error('That API key has spaces or unusual characters: copy it again from platform.comfy.org.');
  const root = `${base}/api/v2`;
  async function call(path, { method = 'GET', headers = {}, body, ok = [200] } = {}) {
    let res;
    try {
      // No cookies and no Referer to `base`: the page URL can carry a shared scene (docs/SECURITY.md).
      res = await fetchFn(`${root}${path}`, {
        method, body, credentials: 'omit', referrerPolicy: 'no-referrer',
        headers: { Authorization: `Bearer ${key}`, ...headers },
      });
    } catch (err) {
      throw new Error(`could not reach ${base} (${redact(err.message, key)}). If this is Comfy Cloud, the browser was probably blocked (CORS): put your worker/ relay's URL here.`);
    }
    if (!ok.includes(res.status)) throw await apiError(res, key);
    return res;
  }
  return {
    base,
    /** Free call that proves the key and the route work: one page of past jobs. */
    check: async () => (await call('/jobs?limit=1')).json(),
    /** POST /assets (multipart): returns the asset {id, hash, file_path, ...}. */
    async upload(blob, name) {
      const form = new FormData();
      form.append('content_type', blob.type || 'application/octet-stream');
      form.append('file_path', name);
      form.append('file', blob, name);
      return (await call('/assets', { method: 'POST', body: form, ok: [200, 201, 202] })).json();
    },
    /** POST /jobs: one new (paid) job. Never retried here. */
    async submit(workflow) {
      const res = await call('/jobs', {
        method: 'POST', ok: [201],
        headers: { 'Content-Type': 'application/json', 'Idempotency-Key': newKey() },
        body: JSON.stringify({ workflow }),
      });
      return res.json();
    },
    getJob: async (id) => (await call(`/jobs/${encodeURIComponent(id)}`)).json(),
    cancel: async (id) => (await call(`/jobs/${encodeURIComponent(id)}/cancel`, { method: 'POST' })).json(),
    /** An output's bytes: GET /assets/{id}/content (Comfy Cloud redirects to signed storage). */
    download: async (assetId) => (await call(`/assets/${encodeURIComponent(assetId)}/content`)).blob(),
  };
}

const TERMINAL = new Set(['succeeded', 'failed', 'canceled', 'expired']);

/** A Comfy job in the render server's state shape, so the panel's describeState() reads it. */
export function panelState(job, kind) {
  const p = job.progress || {};
  const s = {
    id: job.id, kind, cloud: true, status: job.status, stage: job.status, progress: p.value || 0,
    created: job.created_at ? Date.parse(job.created_at) / 1000 : 0, error: null, seconds: null,
  };
  if (job.status === 'running') Object.assign(s, { stage: 'rendering', node: p.current_node_class, step: p.step, steps: p.steps });
  if (job.status === 'canceling') Object.assign(s, { status: 'running', stage: 'cancelling' });
  if (job.status === 'canceled') s.status = 'cancelled';
  if (job.status === 'expired') Object.assign(s, { status: 'failed', error: 'the job expired before it ran' });
  if (job.status === 'failed') {
    const e = job.error || {};
    s.error = `${e.message || 'job failed'}${e.node_id ? ` (node ${e.node_id} ${e.class_type || ''})`.replace(/ \)$/, ')') : ''}`;
  }
  if (TERMINAL.has(job.status) && job.completed_at && job.created_at) {
    s.seconds = Math.round((Date.parse(job.completed_at) - Date.parse(job.created_at)) / 100) / 10;
  }
  return s;
}

/**
 * Submit one graph, poll the job until it ends, download the first `type` ('video'/'image') output of
 * `outputNode`. Resolves {blob, state}; throws with the node error on failure. `signal` cancels like the
 * server path's runJob: before the submit nothing is sent, after it the Comfy job is cancelled too.
 */
export async function runCloudJob(client, graph, { kind, outputNode, type, onUpdate, pollMs = 2000, sleep, signal } = {}) {
  const wait = sleep ?? ((ms) => new Promise((r) => setTimeout(r, ms)));
  const stop = async (id) => {
    if (id) await client.cancel(id).catch(() => {});
    throw new Error(`${kind} cancelled`);
  };
  if (signal?.aborted) await stop(null);
  const t0 = Date.now();
  const stateOf = (j) => {
    const s = panelState(j, kind);
    if (TERMINAL.has(j.status) && s.seconds == null) s.seconds = Math.round((Date.now() - t0) / 100) / 10; // no completed_at
    return s;
  };
  let job = await client.submit(graph);
  onUpdate?.(stateOf(job));
  while (!TERMINAL.has(job.status)) {
    if (signal?.aborted) await stop(job.id);
    await wait(pollMs);
    if (signal?.aborted) await stop(job.id);
    job = await client.getJob(job.id);
    onUpdate?.(stateOf(job));
  }
  const state = stateOf(job);
  if (job.status !== 'succeeded') throw new Error(state.error || `${kind} ${state.status}`);
  const out = (job.outputs || []).find((o) => o.node_id === outputNode && (o.type === type || o.content_type?.startsWith(`${type}/`)));
  if (!out) throw new Error(`job ${job.id} finished without an ${type} from node ${outputNode}`);
  return { blob: await client.download(out.id), state };
}

/** Depth map + prompt -> look still (PNG Blob at width x height), as POST /api/look does on the server. */
export async function cloudLook(client, { depth, prompt, output, seed, strength }, opts = {}) {
  lookSize(output.width, output.height); // validate before uploading anything
  if (!prompt.trim()) throw new Error('prompt is empty');
  if (opts.signal?.aborted) throw new Error('look cancelled');
  opts.onUpdate?.({ kind: 'look', status: 'running', stage: 'uploading' });
  const asset = await client.upload(depth, 'depth.png');
  const graph = buildLookStill({ depth: asset, prompt, width: output.width, height: output.height, seed, strength });
  return runCloudJob(client, graph, { ...opts, kind: 'look', outputNode: LOOK_NODES.output, type: 'image' });
}

/** Layout clip + look still + prompt -> stage-1 render (MP4 Blob), as POST /api/render does on the server. */
export async function cloudRender(client, { mp4, look, lookName, prompt, output, seed }, opts = {}) {
  checkDims(output.width, output.height, output.frames);
  if (!prompt.trim()) throw new Error('prompt is empty');
  if (opts.signal?.aborted) throw new Error('render cancelled');
  opts.onUpdate?.({ kind: 'render', status: 'running', stage: 'uploading' });
  const layout = await client.upload(mp4, 'layout.mp4');
  const lookAsset = await client.upload(look, lookName || 'look.png');
  const graph = buildStage1({ layout, look: lookAsset, prompt, ...output, seed });
  return runCloudJob(client, graph, { ...opts, kind: 'render', outputNode: NODES.output, type: 'video' });
}
